import { StatusBar } from 'expo-status-bar';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, FlatList, Image, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import DateTimePicker from '@react-native-community/datetimepicker';
import { LinearGradient } from 'expo-linear-gradient';
import { completeReminder, deleteRecord, deleteReminder, listRecords, listReminders, type LivoRecord, type RecordType, type Reminder, saveRecord, saveReminder } from '../lib/database';
import { scheduleReminder } from '../lib/reminders';

type Tab = 'home' | 'records' | 'money' | 'reminders' | 'search';
type Overlay = null | 'add' | 'note' | 'transaction' | 'activity' | 'reminder' | 'statements' | 'details' | 'record-detail' | 'reminder-detail';
type Period = 'monthly' | 'yearly' | 'custom';
const forest = '#143e20', moss = '#2e6839', cream = '#fff8e9', gold = '#ffe3a2', ink = '#172218', muted = '#6b6d63';
const initialReminderDate = new Date(Date.now() + 3_600_000);

const fmtDate = (timestamp: number) => new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(timestamp));
const fmtMoney = (value: number, currency = 'INR') => new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0 }).format(value);
const fmtTime = (timestamp: number) => new Intl.DateTimeFormat('en-IN', { hour: 'numeric', minute: '2-digit' }).format(timestamp);
const fmtShortDay = (timestamp: number) => { const date = new Date(timestamp); const today = new Date(); const yesterday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1); return date.toDateString() === today.toDateString() ? 'Today' : date.toDateString() === yesterday.toDateString() ? 'Yesterday' : new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short' }).format(date); };
const startDay = (value: Date) => new Date(value.getFullYear(), value.getMonth(), value.getDate()).getTime();
const number = (value: string | null) => Number(value ?? 0);

export default function LivoHome() {
  const [tab, setTab] = useState<Tab>('home');
  const [overlay, setOverlay] = useState<Overlay>(null);
  const [selectedRecord, setSelectedRecord] = useState<LivoRecord | null>(null);
  const [selectedReminder, setSelectedReminder] = useState<Reminder | null>(null);
  const [records, setRecords] = useState<LivoRecord[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [query, setQuery] = useState('');
  const [period, setPeriod] = useState<Period>('monthly');
  const [referenceDate, setReferenceDate] = useState(new Date());
  const [customStart, setCustomStart] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1));
  const [customEnd, setCustomEnd] = useState(new Date());

  const refresh = useCallback(async () => { setRecords(await listRecords()); setReminders(await listReminders()); }, []);
  useEffect(() => {
    let mounted = true;
    Promise.all([listRecords(), listReminders()]).then(([nextRecords, nextReminders]) => {
      if (mounted) { setRecords(nextRecords); setReminders(nextReminders); }
    }).catch((error) => Alert.alert('Livo could not open data', String(error)));
    return () => { mounted = false; };
  }, []);
  const close = () => { setOverlay(null); refresh(); };

  const selectedRecords = useMemo(() => records.filter((record) => {
    const date = new Date(record.eventDate);
    if (period === 'monthly') return date.getMonth() === referenceDate.getMonth() && date.getFullYear() === referenceDate.getFullYear();
    if (period === 'yearly') return date.getFullYear() === referenceDate.getFullYear();
    return record.eventDate >= startDay(customStart) && record.eventDate <= startDay(customEnd) + 86_399_999;
  }), [records, period, referenceDate, customStart, customEnd]);
  const statement = useMemo(() => totals(selectedRecords), [selectedRecords]);

  return <SafeAreaView style={styles.safe}><StatusBar style="light" />
    <View style={styles.app}>
      {tab === 'home' && <HomeDashboard records={records} onAdd={setOverlay} onRecords={() => setTab('records')} onOpen={(record) => { setSelectedRecord(record); setOverlay('record-detail'); }} />}
      {tab === 'records' && <RecordsScreen records={records} query={query} setQuery={setQuery} onAdd={() => setOverlay('add')} onReminders={() => setTab('reminders')} onOpen={(record) => { setSelectedRecord(record); setOverlay('record-detail'); }} onDelete={async (id) => { await deleteRecord(id); refresh(); }} />}
      {tab === 'money' && <MoneyScreen records={records} onStatements={() => setOverlay('statements')} onAdd={() => setOverlay('transaction')} onOpen={(record) => { setSelectedRecord(record); setOverlay('record-detail'); }} />}
      {tab === 'reminders' && <RemindersScreen reminders={reminders} onAdd={() => setOverlay('reminder')} onOpen={(reminder) => { setSelectedReminder(reminder); setOverlay('reminder-detail'); }} onComplete={async (item) => { await completeReminder(item.id, item.frequency !== 'once'); refresh(); }} onDelete={async (id) => { await deleteReminder(id); refresh(); }} />}
      {tab === 'search' && <SearchScreen records={records} query={query} setQuery={setQuery} onOpen={(record) => { setSelectedRecord(record); setOverlay('record-detail'); }} />}
      <BottomBar tab={tab} setTab={setTab} onAdd={() => setOverlay('add')} />
      <Modal visible={overlay !== null} animationType="slide" transparent={false} onRequestClose={close}>
        {overlay === 'add' && <AddChoice onClose={close} onChoose={setOverlay} />}
        {(overlay === 'note' || overlay === 'transaction' || overlay === 'activity') && <RecordForm type={overlay} onClose={close} />}
        {overlay === 'reminder' && <ReminderForm onClose={close} />}
        {overlay === 'statements' && <StatementScreen period={period} setPeriod={setPeriod} referenceDate={referenceDate} setReferenceDate={setReferenceDate} customStart={customStart} setCustomStart={setCustomStart} customEnd={customEnd} setCustomEnd={setCustomEnd} totals={statement} records={selectedRecords} onDetails={() => setOverlay('details')} onClose={close} />}
        {overlay === 'details' && <StatementDetails totals={statement} records={selectedRecords} onClose={() => setOverlay('statements')} />}
        {overlay === 'record-detail' && selectedRecord && <RecordDetail record={selectedRecord} onClose={close} onDelete={async () => { await deleteRecord(selectedRecord.id); close(); }} />}
        {overlay === 'reminder-detail' && selectedReminder && <ReminderDetail reminder={selectedReminder} onClose={close} onDelete={async () => { await deleteReminder(selectedReminder.id); close(); }} onComplete={async () => { await completeReminder(selectedReminder.id, selectedReminder.frequency !== 'once'); close(); }} />}
      </Modal>
    </View>
  </SafeAreaView>;
}

function ForestBackground({ children }: { children: React.ReactNode }) { return <View style={styles.forestBackground}><Image source={require('../../assets/forest-background.png')} resizeMode="cover" style={[StyleSheet.absoluteFill, styles.forestImage]} /><LinearGradient pointerEvents="none" colors={['rgba(3,18,10,0.12)', 'rgba(3,18,10,0.34)', 'rgba(3,18,10,0.42)']} locations={[0, 0.46, 1]} style={StyleSheet.absoluteFill} />{children}</View>; }
function PaperTexture() { return <Image pointerEvents="none" source={require('../../assets/paper-texture.png')} resizeMode="cover" style={[StyleSheet.absoluteFill, styles.paperTexture]} />; }
function Header({ title, subtitle }: { title: string; subtitle?: string }) { return <View style={styles.header}><Text style={styles.title}>{title}</Text>{subtitle && <Text style={styles.subtitle}>{subtitle}</Text>}</View>; }
function BottomBar({ tab, setTab, onAdd }: { tab: Tab; setTab: (tab: Tab) => void; onAdd: () => void }) { return <View style={styles.bottom}>{([['home', '⌂', 'Home'], ['records', '▤', 'Records']] as const).map(([id, icon, label]) => <Nav key={id} active={tab === id} icon={icon} label={label} onPress={() => setTab(id)} />)}<Pressable accessibilityLabel="Add record" style={styles.addCircle} onPress={onAdd}><Text style={styles.addMark}>＋</Text></Pressable>{([['money', '₹', 'Money'], ['reminders', '♧', 'Reminders'], ['search', '⌕', 'Search']] as const).map(([id, icon, label]) => <Nav key={id} active={tab === id} icon={icon} label={label} onPress={() => setTab(id)} />)}</View>; }
function Nav({ active, icon, label, onPress }: { active: boolean; icon: string; label: string; onPress: () => void }) { return <Pressable style={styles.nav} onPress={onPress}><Text style={[styles.navIcon, active && styles.navActive]}>{icon}</Text><Text style={[styles.navLabel, active && styles.navActive]}>{label}</Text></Pressable>; }

function HomeDashboard({ records, onAdd, onRecords, onOpen }: { records: LivoRecord[]; onAdd: (view: Overlay) => void; onRecords: () => void; onOpen: (record: LivoRecord) => void }) { return <ForestBackground><View style={styles.screen}><View style={styles.homeTop}><Text style={styles.brand}>◒ Livo</Text><Text style={styles.profile}>◯</Text></View><Text style={styles.greeting}>Good evening</Text><Text style={styles.subtitle}>Your life, in one place.</Text><Pressable style={styles.writePrompt} onPress={() => onAdd('note')}><Text style={styles.writeIcon}>□</Text><Text style={styles.writeText}>What happened, did you buy, fix or note today?</Text><Text style={styles.mic}>♩</Text></Pressable><View style={styles.homeQuick}><Quick label="＋ Note" onPress={() => onAdd('note')} /><Quick label="₹ Transaction" onPress={() => onAdd('transaction')} /><Quick label="♧ Reminder" onPress={() => onAdd('reminder')} /><Quick label="⊞ More" onPress={() => onAdd('add')} /></View><View style={styles.layeredCards}><View style={[styles.backCard, styles.backCardOne]} /><View style={[styles.backCard, styles.backCardTwo]} /><View style={styles.homeCard}><PaperTexture /><View style={styles.sectionRow}><Text style={styles.homeRecent}>Recent records</Text><Pressable onPress={onRecords}><Text style={styles.link}>View all ›</Text></Pressable></View>{records.slice(0, 3).map((record) => <RecordRow key={record.id} record={record} onOpen={() => onOpen(record)} />)}{records.length === 0 && <Empty text="Your latest note, transaction, and reminder will appear here." />}</View></View></View></ForestBackground>; }
function Quick({ label, onPress }: { label: string; onPress: () => void }) { return <Pressable style={styles.quick} onPress={onPress}><Text style={styles.quickText}>{label}</Text></Pressable>; }

function RecordsScreen({ records, query, setQuery, onAdd, onReminders, onOpen, onDelete }: { records: LivoRecord[]; query: string; setQuery: (value: string) => void; onAdd: () => void; onReminders: () => void; onOpen: (record: LivoRecord) => void; onDelete: (id: string) => void }) {
  const [filter, setFilter] = useState<'All' | 'Notes' | 'Transactions' | 'Activities'>('All');
  const filtered = records.filter((record) => (filter === 'All' || (filter === 'Notes' && record.type === 'note') || (filter === 'Transactions' && record.type === 'transaction') || (filter === 'Activities' && record.type === 'activity')) && `${record.title} ${record.notes}`.toLowerCase().includes(query.toLowerCase()));
  const grouped = filtered.reduce<{ label: string; records: LivoRecord[] }[]>((groups, record) => {
    const today = new Date(); const day = new Date(record.eventDate);
    const label = day.toDateString() === today.toDateString() ? `Today · ${fmtDate(record.eventDate)}` : day.toDateString() === new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1).toDateString() ? `Yesterday · ${fmtDate(record.eventDate)}` : fmtDate(record.eventDate);
    const last = groups[groups.length - 1];
    if (last?.label === label) last.records.push(record); else groups.push({ label, records: [record] });
    return groups;
  }, []);
  return <ForestBackground><View style={styles.screen}><Header title="Records" subtitle="Your life, in one place." /><View style={styles.searchBox}><Text style={styles.searchGlyph}>⌕</Text><TextInput value={query} onChangeText={setQuery} placeholder="Search your records" placeholderTextColor="#e3e0d3" style={styles.searchInput} /></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['All', 'Notes', 'Activities', 'Transactions', 'Reminders'] as const).map((item) => <Chip key={item} active={filter === item} label={item} onPress={() => item === 'Reminders' ? onReminders() : setFilter(item)} />)}</ScrollView><View style={styles.listPanel}><PaperTexture /><View style={styles.sectionRow}><Text style={styles.sectionTitle}>{query ? `${filtered.length} records found` : 'Recent records'}</Text><Pressable onPress={onAdd}><Text style={styles.link}>＋ Add</Text></Pressable></View><FlatList data={grouped} keyExtractor={(item) => item.label} renderItem={({ item }) => <View style={styles.recordGroup}><Text style={styles.groupLabel}>{item.label}</Text>{item.records.map((record) => <RecordRow key={record.id} record={record} onOpen={() => onOpen(record)} onDelete={() => onDelete(record.id)} />)}</View>} ListEmptyComponent={<Empty text="Add your first record to begin." />} /></View></View></ForestBackground>;
}

function MoneyScreen({ records, onStatements, onAdd, onOpen }: { records: LivoRecord[]; onStatements: () => void; onAdd: () => void; onOpen: (record: LivoRecord) => void }) {
  const [monthOffset, setMonthOffset] = useState(0); const [category, setCategory] = useState('All');
  const shownMonth = new Date(new Date().getFullYear(), new Date().getMonth() + monthOffset, 1);
  const monthRecords = records.filter((record) => { const d = new Date(record.eventDate); return record.type === 'transaction' && d.getMonth() === shownMonth.getMonth() && d.getFullYear() === shownMonth.getFullYear(); });
  const filtered = monthRecords.filter((record) => category === 'All' || (record.category ?? '').toLowerCase().includes(category.toLowerCase()));
  const spent = monthRecords.filter((record) => record.direction === 'expense').reduce((sum, record) => sum + number(record.amount), 0);
  return <ForestBackground><View style={styles.screen}><Header title="Money" subtitle="All your expenses, in one place." /><View style={styles.moneyMonth}><Pressable onPress={() => setMonthOffset((value) => value - 1)}><Text style={styles.monthArrow}>‹</Text></Pressable><Text style={styles.monthTitle}>{new Intl.DateTimeFormat('en-IN', { month: 'long', year: 'numeric' }).format(shownMonth)}</Text><Pressable onPress={() => setMonthOffset((value) => Math.min(0, value + 1))}><Text style={styles.monthArrow}>›</Text></Pressable></View><View style={styles.spendingCard}><PaperTexture /><Text style={styles.spendingLabel}>Total spent</Text><View style={styles.spendingRow}><Text style={styles.spendingValue}>{fmtMoney(spent)}</Text><Pressable onPress={onStatements}><Text style={styles.link}>Statements ›</Text></Pressable></View></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{['All', 'Food', 'Shopping', 'Travel', 'Other'].map((item) => <Chip key={item} active={category === item} label={item} onPress={() => setCategory(item)} />)}</ScrollView><View style={styles.listPanel}><PaperTexture /><View style={styles.sectionRow}><Text style={styles.sectionTitle}>Transactions</Text><Pressable onPress={onAdd}><Text style={styles.link}>＋ Add</Text></Pressable></View><FlatList data={filtered} keyExtractor={(item) => item.id} renderItem={({ item }) => <Pressable onPress={() => onOpen(item)} style={styles.transactionRow}><PaperTexture /><Text style={styles.rowIcon}>{item.direction === 'income' ? '↙' : '▧'}</Text><View style={styles.rowBody}><Text style={styles.rowTitle}>{item.title}</Text><Text style={styles.rowMeta}>{item.category || fmtDate(item.eventDate)}</Text></View><Text style={styles.transactionAmount}>{item.direction === 'income' ? '+' : '−'}{fmtMoney(number(item.amount), item.currency)}</Text></Pressable>} ListEmptyComponent={<Empty text="Add an income or expense to see it here." />} /><PrimaryButton label="＋ Add Transaction" onPress={onAdd} /></View></View></ForestBackground>;
}

function RemindersScreen({ reminders, onAdd, onOpen, onComplete, onDelete }: { reminders: Reminder[]; onAdd: () => void; onOpen: (reminder: Reminder) => void; onComplete: (item: Reminder) => void; onDelete: (id: string) => void }) { const [completed, setCompleted] = useState(false); const items = reminders.filter((item) => completed ? !item.enabled : Boolean(item.enabled)); const now = new Date().getTime(); const upcoming = items.filter((item) => item.dueAt >= now && item.dueAt <= now + 7 * 86_400_000); return <ForestBackground><View style={styles.screen}><Header title="Reminders" subtitle="Things to remember and do, on time." /><View style={styles.toggle}><Pressable onPress={() => setCompleted(false)} style={!completed ? styles.toggleOn : undefined}><Text style={!completed ? styles.toggleText : styles.toggleOff}>Upcoming  {reminders.filter((item) => item.enabled).length}</Text></Pressable><Pressable onPress={() => setCompleted(true)} style={completed ? styles.toggleOn : undefined}><Text style={completed ? styles.toggleText : styles.toggleOff}>Completed</Text></Pressable></View><View style={styles.listPanel}><ScrollView style={styles.reminderScroll} contentContainerStyle={styles.reminderContent}><View style={styles.reminderPaper}><PaperTexture />{items.map((item) => <Pressable key={item.id} onPress={() => onOpen(item)} style={styles.reminderRow}><Text style={styles.rowIcon}>♧</Text><View style={styles.rowBody}><Text style={styles.rowTitle}>{item.title}</Text><Text style={styles.rowMeta}>{item.frequency === 'once' ? fmtDate(item.dueAt) : `${item.frequency[0].toUpperCase()}${item.frequency.slice(1)} · ${new Intl.DateTimeFormat('en-IN', { hour: 'numeric', minute: '2-digit' }).format(item.dueAt)}`}</Text></View>{item.enabled ? <Pressable accessibilityLabel="Mark reminder complete" onPress={() => onComplete(item)} style={styles.reminderCheck}><Text style={styles.done}>✓</Text></Pressable> : null}<Pressable accessibilityLabel="Delete reminder" onPress={() => onDelete(item.id)}><Text style={styles.delete}>×</Text></Pressable></Pressable>)}{items.length === 0 && <Empty text={completed ? 'No completed reminders.' : 'No upcoming reminders.'} />}</View>{!completed && <><Text style={styles.upcomingTitle}>▣  Next 7 days</Text><View style={styles.upcomingCard}>{upcoming.length ? upcoming.slice(0, 3).map((item) => <Pressable key={item.id} onPress={() => onOpen(item)} style={styles.upcomingRow}><Text style={styles.rowIcon}>♧</Text><View style={styles.rowBody}><Text style={styles.upcomingName}>{item.title}</Text><Text style={styles.upcomingMeta}>{fmtDate(item.dueAt)} · {item.frequency}</Text></View><Text style={styles.chevron}>›</Text></Pressable>) : <Text style={styles.upcomingMeta}>Nothing due in the next week.</Text>}</View></>}</ScrollView><PrimaryButton label="＋ Add Reminder" onPress={onAdd} /></View></View></ForestBackground>; }

function SearchScreen({ records, query, setQuery, onOpen }: { records: LivoRecord[]; query: string; setQuery: (value: string) => void; onOpen: (record: LivoRecord) => void }) { const [filter, setFilter] = useState<'All' | 'Notes' | 'Transactions' | 'Activities'>('All'); const found = records.filter((record) => (!query || `${record.title} ${record.notes} ${record.category ?? ''}`.toLowerCase().includes(query.toLowerCase())) && (filter === 'All' || (filter === 'Notes' && record.type === 'note') || (filter === 'Transactions' && record.type === 'transaction') || (filter === 'Activities' && record.type === 'activity'))); const suggestions = [...new Set(records.slice(0, 4).map((item) => item.title))]; return <ForestBackground><View style={styles.screen}><Header title="Search Records" subtitle="Find anything from your life." /><View style={styles.searchBox}><Text style={styles.searchGlyph}>⌕</Text><TextInput value={query} onChangeText={setQuery} placeholder="Search your records…" placeholderTextColor="#e3e0d3" style={styles.searchInput} /><Pressable onPress={() => setQuery('')}><Text style={styles.clearSearch}>×</Text></Pressable></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['All', 'Notes', 'Transactions', 'Activities'] as const).map((item) => <Chip key={item} active={filter === item} label={item} onPress={() => setFilter(item)} />)}</ScrollView><View style={styles.listPanel}>{query ? <><View style={styles.sectionRow}><Text style={styles.sectionTitle}>{found.length} records found</Text><Text style={styles.sortLabel}>Newest first ↓</Text></View><FlatList data={found} keyExtractor={(item) => item.id} renderItem={({ item }) => <RecordRow record={item} onOpen={() => onOpen(item)} />} ListEmptyComponent={<Empty text="No matching records." />} /></> : <ScrollView><Text style={styles.sectionTitle}>Recent searches</Text>{suggestions.length ? suggestions.map((term) => <Pressable key={term} style={styles.suggestion} onPress={() => setQuery(term)}><Text style={styles.suggestionIcon}>◷</Text><Text style={styles.suggestionText}>{term}</Text><Text style={styles.chevron}>›</Text></Pressable>) : <Empty text="Your searches will appear here." />}</ScrollView>}</View></View></ForestBackground>; }

function AddChoice({ onClose, onChoose }: { onClose: () => void; onChoose: (overlay: Overlay) => void }) { return <FormShell title="Add Record" onClose={onClose}><Text style={styles.formIntro}>What would you like to add?</Text><View style={styles.choiceGrid}>{([['note', '▤', 'Note', 'Write anything'], ['transaction', '₹', 'Transaction', 'Money in or out'], ['reminder', '♧', 'Reminder', 'Get a notification'], ['activity', '⚑', 'Activity', 'Track an activity']] as const).map(([type, icon, title, detail]) => <Pressable key={type} style={styles.choice} onPress={() => onChoose(type)}><Text style={styles.choiceIcon}>{icon}</Text><Text style={styles.choiceTitle}>{title}</Text><Text style={styles.choiceDetail}>{detail}</Text></Pressable>)}</View></FormShell>; }

function RecordForm({ type, onClose }: { type: Exclude<RecordType, 'transaction'> | 'transaction'; onClose: () => void }) {
  const transaction = type === 'transaction'; const [title, setTitle] = useState(''); const [notes, setNotes] = useState(''); const [amount, setAmount] = useState(''); const [category, setCategory] = useState(''); const [date, setDate] = useState(new Date()); const [direction, setDirection] = useState<'expense' | 'income'>('expense'); const [showDate, setShowDate] = useState(false);
  const save = async () => { if (!title.trim()) return Alert.alert('Add a title', transaction ? 'For example: Groceries' : 'Describe what happened.'); if (transaction && (!amount || Number.isNaN(Number(amount)) || Number(amount) < 0)) return Alert.alert('Enter a valid amount'); await saveRecord({ id: `${Date.now()}-${Math.random()}`, eventDate: startDay(date), eventTime: date.getTime(), type, title: title.trim(), notes, amount: transaction ? amount : null, currency: 'INR', category: category.trim() || null, direction: transaction ? direction : null }); onClose(); };
  return <FormShell title={transaction ? 'Add Transaction' : type === 'note' ? 'Add Note' : 'Add Activity'} onClose={onClose}><Text style={styles.formIntro}>{transaction ? 'Track money in or out.' : type === 'note' ? 'Capture a thought while it is fresh.' : 'Keep a note of what happened.'}</Text>{transaction && <View style={styles.toggle}><Pressable onPress={() => setDirection('expense')} style={direction === 'expense' ? styles.toggleOn : undefined}><Text style={direction === 'expense' ? styles.toggleText : styles.toggleOff}>Expense</Text></Pressable><Pressable onPress={() => setDirection('income')} style={direction === 'income' ? styles.toggleOn : undefined}><Text style={direction === 'income' ? styles.toggleText : styles.toggleOff}>Income</Text></Pressable></View>}{transaction && <Field label="₹ Amount" value={amount} onChangeText={setAmount} keyboardType="decimal-pad" />}<Field label={transaction ? 'What was it?' : type === 'note' ? 'Write your note…' : 'What happened?'} value={title} onChangeText={setTitle} multiline={type === 'note'} />{transaction && <Field label="Category (e.g. Groceries)" value={category} onChangeText={setCategory} />}{type !== 'note' && <Field label="Note (optional)" value={notes} onChangeText={setNotes} multiline />}{type === 'note' && <Field label="Tags or details (optional)" value={notes} onChangeText={setNotes} multiline />}{!transaction && <><Text style={styles.fieldLabel}>When did it happen?</Text><View style={styles.dateChoiceRow}>{(['Today', 'Yesterday', 'Another date'] as const).map((choice) => { const chosen = choice === 'Today' ? fmtShortDay(date.getTime()) === 'Today' : choice === 'Yesterday' ? fmtShortDay(date.getTime()) === 'Yesterday' : fmtShortDay(date.getTime()) !== 'Today' && fmtShortDay(date.getTime()) !== 'Yesterday'; return <Pressable key={choice} onPress={() => { if (choice === 'Today') setDate(new Date()); else if (choice === 'Yesterday') { const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1); setDate(yesterday); } else setShowDate(true); }} style={[styles.dateChoice, chosen && styles.dateChoiceActive]}><Text style={[styles.dateChoiceText, chosen && styles.dateChoiceTextActive]}>{choice}</Text></Pressable>; })}</View></>}{showDate && <DateTimePicker value={date} mode="date" onChange={(_, next) => { setShowDate(Platform.OS === 'ios'); if (next) setDate(next); }} />}<Pressable style={styles.dateRow} onPress={() => setShowDate(true)}><Text>▣  Date</Text><Text>{fmtDate(date.getTime())} ›</Text></Pressable><PrimaryButton label={transaction ? 'Save Transaction' : type === 'note' ? 'Save Note' : 'Save Activity'} onPress={save} /></FormShell>;
}

function ReminderForm({ onClose }: { onClose: () => void }) { const [title, setTitle] = useState(''); const [notes, setNotes] = useState(''); const [date, setDate] = useState(initialReminderDate); const [frequency, setFrequency] = useState<Reminder['frequency']>('once'); const [picker, setPicker] = useState<'date' | 'time' | null>(null); const save = async () => { if (!title.trim()) return Alert.alert('Add a reminder'); const base: Reminder = { id: `${Date.now()}-${Math.random()}`, title: title.trim(), notes, dueAt: date.getTime(), frequency, enabled: 1, notificationId: null, createdAt: Date.now(), updatedAt: Date.now() }; const notificationId = await scheduleReminder(base); await saveReminder({ ...base, notificationId }); onClose(); }; return <FormShell title="Add Reminder" onClose={onClose}><Field label="What to remind you?" value={title} onChangeText={setTitle} /><Field label="Notes (optional)" value={notes} onChangeText={setNotes} multiline />{picker && <DateTimePicker value={date} mode={picker} onChange={(_, next) => { setPicker(Platform.OS === 'ios' ? picker : null); if (next) setDate(next); }} />}<Pressable style={styles.dateRow} onPress={() => setPicker('date')}><Text>▣  Date</Text><Text>{fmtDate(date.getTime())} ›</Text></Pressable><Pressable style={styles.dateRow} onPress={() => setPicker('time')}><Text>◷  Time</Text><Text>{new Intl.DateTimeFormat('en-IN', { hour: 'numeric', minute: '2-digit' }).format(date)} ›</Text></Pressable><Text style={styles.fieldLabel}>Repeat</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['once', 'daily', 'weekly', 'monthly'] as const).map((item) => <Chip key={item} active={frequency === item} label={item[0].toUpperCase() + item.slice(1)} onPress={() => setFrequency(item)} />)}</ScrollView><PrimaryButton label="Save Reminder" onPress={save} /></FormShell>; }

function StatementScreen({ period, setPeriod, referenceDate, setReferenceDate, customStart, setCustomStart, customEnd, setCustomEnd, totals: statement, records, onDetails, onClose }: { period: Period; setPeriod: (value: Period) => void; referenceDate: Date; setReferenceDate: (date: Date) => void; customStart: Date; setCustomStart: (date: Date) => void; customEnd: Date; setCustomEnd: (date: Date) => void; totals: Totals; records: LivoRecord[]; onDetails: () => void; onClose: () => void }) { const [picker, setPicker] = useState<'reference' | 'start' | 'end' | null>(null); const shift = (amount: number) => { const next = new Date(referenceDate); if (period === 'yearly') next.setFullYear(next.getFullYear() + amount); else next.setMonth(next.getMonth() + amount); setReferenceDate(next); }; const value = picker === 'start' ? customStart : picker === 'end' ? customEnd : referenceDate; return <FormShell title="Statements" onClose={onClose}><View style={styles.toggle}>{(['monthly', 'yearly', 'custom'] as const).map((item) => <Pressable key={item} style={period === item ? styles.toggleOn : undefined} onPress={() => setPeriod(item)}><Text style={period === item ? styles.toggleText : styles.toggleOff}>{item[0].toUpperCase() + item.slice(1)}</Text></Pressable>)}</View>{picker && <DateTimePicker value={value} mode={period === 'yearly' && picker === 'reference' ? 'date' : 'date'} onChange={(_, next) => { if (!next) return setPicker(null); if (picker === 'start') setCustomStart(next); else if (picker === 'end') setCustomEnd(next); else setReferenceDate(next); if (Platform.OS !== 'ios') setPicker(null); }} />}{period === 'custom' ? <><Pressable style={styles.dateRow} onPress={() => setPicker('start')}><Text>▣  From</Text><Text>{fmtDate(customStart.getTime())} ›</Text></Pressable><Pressable style={styles.dateRow} onPress={() => setPicker('end')}><Text>▣  To</Text><Text>{fmtDate(customEnd.getTime())} ›</Text></Pressable></> : <View style={styles.monthNav}><Pressable onPress={() => shift(-1)}><Text style={styles.arrow}>‹</Text></Pressable><Pressable onPress={() => setPicker('reference')}><Text style={styles.monthTitle}>{new Intl.DateTimeFormat('en-IN', period === 'yearly' ? { year: 'numeric' } : { month: 'short', year: 'numeric' }).format(referenceDate)}</Text></Pressable><Pressable onPress={() => shift(1)}><Text style={styles.arrow}>›</Text></Pressable></View>}<SummaryRows data={statement} />{period === 'yearly' ? <MonthBreakdown records={records} /> : <PrimaryButton label="View Details  ›" onPress={onDetails} />}</FormShell>; }

function StatementDetails({ totals: statement, records, onClose }: { totals: Totals; records: LivoRecord[]; onClose: () => void }) { const categories = Object.entries(records.filter((x) => x.type === 'transaction' && x.direction === 'expense').reduce<Record<string, number>>((all, item) => { const key = item.category || 'Uncategorized'; all[key] = (all[key] ?? 0) + number(item.amount); return all; }, {})).sort((a, b) => b[1] - a[1]); return <FormShell title="Statement Details" onClose={onClose}><Text style={styles.rangeLabel}>{records.length ? `${fmtDate(records.at(-1)!.eventDate)} – ${fmtDate(records[0].eventDate)}` : 'No transactions'}</Text><SummaryRows data={statement} /><Text style={styles.sectionTitle}>By Category</Text>{categories.map(([category, amount]) => <View key={category} style={styles.row}><Text style={styles.rowIcon}>▧</Text><Text style={styles.rowBody}>{category}</Text><Text style={styles.rowTitle}>{fmtMoney(amount)}</Text></View>)}{categories.length === 0 && <Empty text="No expenses in this period." />}</FormShell>; }

function RecordDetail({ record, onClose, onDelete }: { record: LivoRecord; onClose: () => void; onDelete: () => Promise<void> }) { return <FormShell title={record.type === 'transaction' ? 'Transaction Details' : record.type === 'note' ? 'Note Details' : 'Activity Details'} onClose={onClose}><View style={styles.detailHero}><Text style={styles.detailIcon}>{record.type === 'transaction' ? '▧' : record.type === 'note' ? '▤' : '⚑'}</Text><Text style={styles.detailTitle}>{record.title}</Text>{record.amount && <Text style={styles.detailAmount}>{fmtMoney(number(record.amount), record.currency)}</Text>}</View><View style={styles.detailRows}><View style={styles.dateRow}><Text>▣  Date</Text><Text>{fmtDate(record.eventDate)}</Text></View><View style={styles.dateRow}><Text>⌁  Type</Text><Text>{record.type}</Text></View>{record.category && <View style={styles.dateRow}><Text>▱  Category</Text><Text>{record.category}</Text></View>}{record.notes ? <View style={styles.notesBox}><Text style={styles.fieldLabel}>Notes</Text><Text style={styles.notesText}>{record.notes}</Text></View> : null}</View><Pressable style={styles.deleteButton} onPress={() => { Alert.alert('Delete record?', 'This cannot be undone.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => { onDelete(); } }]); }}><Text style={styles.deleteButtonText}>Delete Record</Text></Pressable></FormShell>; }

function ReminderDetail({ reminder, onClose, onDelete, onComplete }: { reminder: Reminder; onClose: () => void; onDelete: () => Promise<void>; onComplete: () => Promise<void> }) { return <FormShell title="Reminder Details" onClose={onClose}><View style={styles.detailHero}><Text style={styles.detailIcon}>♧</Text><Text style={styles.detailTitle}>{reminder.title}</Text></View><View style={styles.detailRows}><View style={styles.dateRow}><Text>▣  Date</Text><Text>{fmtDate(reminder.dueAt)}</Text></View><View style={styles.dateRow}><Text>◷  Time</Text><Text>{new Intl.DateTimeFormat('en-IN', { hour: 'numeric', minute: '2-digit' }).format(reminder.dueAt)}</Text></View><View style={styles.dateRow}><Text>⟳  Repeat</Text><Text>{reminder.frequency}</Text></View>{reminder.notes ? <View style={styles.notesBox}><Text style={styles.fieldLabel}>Notes</Text><Text style={styles.notesText}>{reminder.notes}</Text></View> : null}</View>{reminder.enabled ? <PrimaryButton label="Mark Complete" onPress={() => { onComplete(); }} /> : null}<Pressable style={styles.deleteButton} onPress={() => { Alert.alert('Delete reminder?', 'This cannot be undone.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => { onDelete(); } }]); }}><Text style={styles.deleteButtonText}>Delete Reminder</Text></Pressable></FormShell>; }

type Totals = { income: number; expense: number; balance: number };
function totals(records: LivoRecord[]): Totals { const income = records.filter((x) => x.type === 'transaction' && x.direction === 'income').reduce((sum, x) => sum + number(x.amount), 0); const expense = records.filter((x) => x.type === 'transaction' && x.direction === 'expense').reduce((sum, x) => sum + number(x.amount), 0); return { income, expense, balance: income - expense }; }
function SummaryRows({ data }: { data: Totals }) { return <View style={styles.summary}><Summary label="↓  Income" amount={data.income} /><Summary label="↑  Expenses" amount={data.expense} /><Summary label="▰  Net Balance" amount={data.balance} strong /></View>; }
function Summary({ label, amount, strong }: { label: string; amount: number; strong?: boolean }) { return <View style={[styles.summaryRow, strong && styles.balance]}><Text style={styles.summaryLabel}>{label}</Text><Text style={styles.summaryAmount}>{fmtMoney(amount)}</Text></View>; }
function MonthBreakdown({ records }: { records: LivoRecord[] }) { const months = new Map<string, LivoRecord[]>(); records.forEach((record) => { const label = new Intl.DateTimeFormat('en-IN', { month: 'short', year: 'numeric' }).format(new Date(record.eventDate)); months.set(label, [...(months.get(label) ?? []), record]); }); return <View><Text style={styles.sectionTitle}>Month-wise Summary</Text>{[...months.entries()].map(([month, items]) => <View key={month} style={styles.row}><Text style={styles.rowBody}>{month}</Text><Text style={styles.rowTitle}>{fmtMoney(totals(items).balance)}</Text></View>)}</View>; }
function FormShell({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <SafeAreaView style={styles.safe}><ForestBackground><View style={styles.formScreen}><View style={styles.formHeader}><Pressable onPress={onClose}><Text style={styles.back}>‹</Text></Pressable><Text style={styles.formTitle}>{title}</Text></View><ScrollView style={styles.formScroll} contentContainerStyle={styles.formCard}>{children}</ScrollView><ReferenceDock /></View></ForestBackground></SafeAreaView>; }
function ReferenceDock() { return <View style={styles.referenceDock}><View style={styles.nav}><Text style={styles.navIcon}>▣</Text><Text style={styles.navLabel}>Records</Text></View><View style={styles.nav}><Text style={styles.navIcon}>₹</Text><Text style={styles.navLabel}>Money</Text></View><View style={styles.dockAdd}><Text style={styles.addMark}>＋</Text></View><View style={styles.nav}><Text style={styles.navIcon}>♧</Text><Text style={styles.navLabel}>Reminders</Text></View><View style={styles.nav}><Text style={styles.navIcon}>⌕</Text><Text style={styles.navLabel}>Search</Text></View></View>; }
function Field({ label, value, onChangeText, multiline, keyboardType }: { label: string; value: string; onChangeText: (value: string) => void; multiline?: boolean; keyboardType?: 'decimal-pad' }) { return <View><Text style={styles.fieldLabel}>{label}</Text><TextInput value={value} onChangeText={onChangeText} multiline={multiline} keyboardType={keyboardType} style={[styles.field, multiline && styles.fieldMulti]} placeholder={label} placeholderTextColor="#89877d" /></View>; }
function Chip({ active, label, onPress }: { active: boolean; label: string; onPress: () => void }) { return <Pressable style={[styles.chip, active && styles.chipActive]} onPress={onPress}><Text style={[styles.chipText, active && styles.chipTextActive]}>{label}</Text></Pressable>; }
function PrimaryButton({ label, onPress }: { label: string; onPress: () => void }) { return <Pressable style={styles.primary} onPress={onPress}><Text style={styles.primaryText}>{label}</Text></Pressable>; }
function RecordRow({ record, onOpen, onDelete }: { record: LivoRecord; onOpen?: () => void; onDelete?: () => void }) { return <Pressable onPress={onOpen} disabled={!onOpen} style={styles.row}><PaperTexture /><Text style={[styles.rowIcon, record.type === 'note' && styles.noteIcon, record.type === 'activity' && styles.activityIcon]}>{record.type === 'transaction' ? '▧' : record.type === 'note' ? '▤' : '⚑'}</Text><View style={styles.rowBody}><Text style={styles.rowTitle}>{record.title}{record.amount ? ` · ${fmtMoney(number(record.amount), record.currency)}` : ''}</Text><Text style={styles.rowMeta}>{fmtShortDay(record.eventDate)} · {record.type} · {fmtTime(record.eventTime)}</Text></View>{onDelete && <Pressable onPress={onDelete}><Text style={styles.delete}>×</Text></Pressable>}{onOpen && !onDelete && <Text style={styles.chevron}>›</Text>}</Pressable>; }
function Empty({ text }: { text: string }) { return <View style={styles.empty}><Text style={styles.emptyText}>{text}</Text></View>; }

